//! 🌱️ A lifetime owner admits four real arena backings and a stable header before publishing any borrow.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetirementDemand,ValueError,ValueRefusalKind,retained_clone::retained_clone_grant_admits};
use std::{alloc::Layout,mem::ManuallyDrop};
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"UI arena opening or physical custody is invalid")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
fn empty_arena()->UiValueArena{UiValueArena{pages:Box::default(),collections:Box::default(),free_pages:Box::default(),free_page_count:0,free_collections:Box::default(),free_collection_count:0,retirement_head:UI_VALUE_NONE,retirement_tail:UI_VALUE_NONE,retirement_len:0,handback_cursor:0,items:0,bytes:0}}
fn allocation<T>(count:usize)->Result<RetirementDemand,ValueError>{let capacity_bytes=count.checked_mul(size_of::<T>()).filter(|n|*n<=isize::MAX as usize).ok_or_else(invalid)?;Ok(RetirementDemand{capacity_bytes,..fixed(size_of::<Vec<T>>())})}
fn release_vec_demand<T>(value:&Vec<T>)->RetirementDemand{RetirementDemand{release_bytes:value.capacity()*size_of::<T>(),..fixed(size_of::<Vec<T>>())}}
fn release_empty_vec<T>(value:&mut Vec<T>){unsafe{value.set_len(0)}drop(std::mem::take(value));}
fn release_empty_box<T>(value:&mut Box<[T]>){let old=std::mem::take(value);let len=old.len();let pointer=Box::into_raw(old).cast::<T>();let layout=Layout::array::<T>(len).expect("quoted native arena extent");if layout.size()!=0{unsafe{std::alloc::dealloc(pointer.cast(),layout)}}}
/// 🧷️ This opaque stable allocation contains only unpublished or fully audited empty arena rows.
pub struct UiArenaBacking{pub(super) arena:ManuallyDrop<Option<Box<UiValueArena>>>}
impl UiArenaBacking{
 fn empty()->Self{Self{arena:ManuallyDrop::new(None)}}
 pub fn terminal_is_empty(&self)->bool{self.arena.is_none()}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{let Some(arena)=self.arena.as_ref()else{return Ok(Default::default())};let release_bytes=if !arena.pages.is_empty(){arena.pages.len()*size_of::<UiPageSlot>()}else if !arena.collections.is_empty(){arena.collections.len()*size_of::<UiCollectionSlot>()}else if !arena.free_pages.is_empty(){arena.free_pages.len()*size_of::<usize>()}else if !arena.free_collections.is_empty(){arena.free_collections.len()*size_of::<usize>()}else{size_of::<UiValueArena>()};Ok(RetirementDemand{release_bytes,..fixed(size_of::<UiValueArena>())})}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{let mut work=0;let result=(||{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands()?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}work=1;let arena=self.arena.as_mut().ok_or_else(invalid)?;if !arena.pages.is_empty(){release_empty_box(&mut arena.pages)}else if !arena.collections.is_empty(){release_empty_box(&mut arena.collections)}else if !arena.free_pages.is_empty(){release_empty_box(&mut arena.free_pages)}else if !arena.free_collections.is_empty(){release_empty_box(&mut arena.free_collections)}else{let pointer=Box::into_raw(self.arena.take().ok_or_else(invalid)?);unsafe{std::alloc::dealloc(pointer.cast(),Layout::new::<UiValueArena>())}}Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(receipt(d))}else{RetainedCloneStep::Progress(receipt(d))})})();RetainedWorkOutcome{result,work}}
 pub(super) fn pointer(&self)->Result<usize,ValueError>{self.arena.as_ref().map(|arena|arena.as_ref()as*const UiValueArena as usize).ok_or_else(invalid)}
}
impl Drop for UiArenaBacking{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"UI arena backing requires paid physical closure")}}
/// 🪴️ Each call allocates one backing, initializes one fixed row, or transfers only already funded metadata.
pub struct UiArenaOpening{backing:UiArenaBacking,pages:ManuallyDrop<Vec<UiPageSlot>>,collections:ManuallyDrop<Vec<UiCollectionSlot>>,free_pages:ManuallyDrop<Vec<usize>>,free_collections:ManuallyDrop<Vec<usize>>,phase:u8,faulted:bool,closing:bool}
impl UiArenaOpening{
 pub fn new()->Self{Self{backing:UiArenaBacking::empty(),pages:ManuallyDrop::new(Vec::new()),collections:ManuallyDrop::new(Vec::new()),free_pages:ManuallyDrop::new(Vec::new()),free_collections:ManuallyDrop::new(Vec::new()),phase:0,faulted:false,closing:false}}
 pub fn constructor_demand()->RetirementDemand{fixed(size_of::<Self>())}
 pub fn phase(&self)->&'static str{match self.phase{0=>"header",1=>"pageAllocation",2=>"pageInitialization",3=>"collectionAllocation",4=>"collectionInitialization",5=>"freePageAllocation",6=>"freePageInitialization",7=>"freeCollectionAllocation",8=>"freeCollectionInitialization",9=>"seal",10=>"ready",_=>"spent"}}
 pub fn ready(&self)->bool{self.phase==10&&!self.faulted&&!self.closing}
 pub fn demands(&self)->Result<RetirementDemand,ValueError>{if self.faulted||self.closing{return Err(invalid())}Ok(match self.phase{0=>RetirementDemand{capacity_bytes:size_of::<UiValueArena>(),..fixed(size_of::<UiValueArena>())},1=>allocation::<UiPageSlot>(UI_VALUE_AGGREGATE_ITEMS)?,2=>fixed(size_of::<UiPageSlot>()+size_of::<usize>()),3=>allocation::<UiCollectionSlot>(UI_VALUE_ADMISSION_SLOTS)?,4=>fixed(size_of::<UiCollectionSlot>()+size_of::<usize>()),5=>allocation::<usize>(UI_VALUE_AGGREGATE_ITEMS)?,6=>fixed(2*size_of::<usize>()),7=>allocation::<usize>(UI_VALUE_ADMISSION_SLOTS)?,8=>fixed(2*size_of::<usize>()),9=>fixed(size_of::<UiValueArena>()+4*size_of::<Vec<usize>>()),10=>fixed(size_of::<UiArenaBacking>()),_=>return Err(invalid())})}
 pub fn advance(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{let mut work=0;let result=(||{if self.ready(){return Ok(RetainedCloneStep::Complete(Default::default()))}let mut d=self.demands()?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}work=1;
  macro_rules! reserve{($field:ident,$count:expr,$type:ty,$next:expr)=>{{let attempted=self.$field.try_reserve_exact($count);d.capacity_bytes=self.$field.capacity()*size_of::<$type>();if attempted.is_err()||!retained_clone_grant_admits(g,d){self.faulted=true;return Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"UI arena physical backing admission refused").with_retained_progress(receipt(d)))}self.phase=$next;}}}
  match self.phase{
   0=>{*self.backing.arena=Some(Box::new(empty_arena()));self.phase=1;},1=>reserve!(pages,UI_VALUE_AGGREGATE_ITEMS,UiPageSlot,2),2=>if self.pages.len()<self.pages.capacity(){self.pages.push(UiPageSlot::default())}else{self.phase=3},3=>reserve!(collections,UI_VALUE_ADMISSION_SLOTS,UiCollectionSlot,4),4=>if self.collections.len()<self.collections.capacity(){self.collections.push(UiCollectionSlot::default())}else{self.phase=5},5=>reserve!(free_pages,UI_VALUE_AGGREGATE_ITEMS,usize,6),6=>if self.free_pages.len()<self.free_pages.capacity(){let index=self.free_pages.len();self.free_pages.push(UI_VALUE_AGGREGATE_ITEMS.saturating_sub(index+1))}else{self.phase=7},7=>reserve!(free_collections,UI_VALUE_ADMISSION_SLOTS,usize,8),8=>if self.free_collections.len()<self.free_collections.capacity(){let index=self.free_collections.len();self.free_collections.push(UI_VALUE_ADMISSION_SLOTS.saturating_sub(index+1))}else{self.phase=9},
   9=>{let arena=self.backing.arena.as_mut().ok_or_else(invalid)?;arena.pages=std::mem::take(&mut*self.pages).into_boxed_slice();arena.collections=std::mem::take(&mut*self.collections).into_boxed_slice();arena.free_pages=std::mem::take(&mut*self.free_pages).into_boxed_slice();arena.free_collections=std::mem::take(&mut*self.free_collections).into_boxed_slice();arena.free_page_count=UI_VALUE_AGGREGATE_ITEMS;arena.free_collection_count=UI_VALUE_ADMISSION_SLOTS;self.phase=10;},_=>return Err(invalid())}
  Ok(if self.ready(){RetainedCloneStep::Complete(receipt(d))}else{RetainedCloneStep::Progress(receipt(d))})})();RetainedWorkOutcome{result,work}}
 pub fn take(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<Option<(UiArenaBacking,RetainedCloneProgress)>>{let d=fixed(size_of::<UiArenaBacking>());if !self.ready()||!retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(None),work:0}}self.phase=11;RetainedWorkOutcome{result:Ok(Some((std::mem::replace(&mut self.backing,UiArenaBacking::empty()),receipt(d)))),work:1}}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if self.pages.capacity()!=0{return Ok(release_vec_demand(&self.pages))}if self.collections.capacity()!=0{return Ok(release_vec_demand(&self.collections))}if self.free_pages.capacity()!=0{return Ok(release_vec_demand(&self.free_pages))}if self.free_collections.capacity()!=0{return Ok(release_vec_demand(&self.free_collections))}self.backing.close_demands()}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{let d=match self.close_demands(){Ok(d)=>d,Err(error)=>return RetainedWorkOutcome{result:Err(error),work:0}};if self.terminal_is_empty(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}self.closing=true;if self.pages.capacity()!=0{release_empty_vec(&mut self.pages)}else if self.collections.capacity()!=0{release_empty_vec(&mut self.collections)}else if self.free_pages.capacity()!=0{release_empty_vec(&mut self.free_pages)}else if self.free_collections.capacity()!=0{release_empty_vec(&mut self.free_collections)}else{return self.backing.close_step(g)}RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(receipt(d))),work:1}}
 pub fn terminal_is_empty(&self)->bool{self.pages.capacity()==0&&self.collections.capacity()==0&&self.free_pages.capacity()==0&&self.free_collections.capacity()==0&&self.backing.terminal_is_empty()}
}
impl Drop for UiArenaOpening{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"UI arena opening retains every partial native backing until paid closure")}}
